from pathlib import Path
import base64,gzip

root=Path(__file__).resolve().parents[1]
payloads={"1401":"","1402":"","1403":"","1404":"","summary":"","report":""}
targets={
 "1401":"data/capacity/normalized/1401/capacities-health-management-hit.csv",
 "1402":"data/capacity/normalized/1402/capacities-health-management-hit.csv",
 "1403":"data/capacity/normalized/1403/capacities-health-management-hit.csv",
 "1404":"data/capacity/normalized/1404/capacities-health-management-hit.csv",
 "summary":"data/capacity/HEALTH_MANAGEMENT_HIT_SUMMARY.json",
 "report":"data/capacity/HEALTH_MANAGEMENT_HIT_REPORT.md",
}
for k,rel in targets.items():
    out=root/rel
    out.parent.mkdir(parents=True,exist_ok=True)
    out.write_bytes(gzip.decompress(base64.b64decode(payloads[k])))
    print("wrote",rel)
